q2:
SELECT d.name FROM drinker d
WHERE d.name NOT IN (
    SELECT drinker FROM likes
    WHERE beer = 'Corona'
) 
AND d.name IN (
    SELECT f.drinker FROM frequents f
    JOIN serves s ON f.bar = s.bar
    WHERE s.beer = 'Corona'
);

